/* LevelMonSwc: Level monitor (weighted average, hysteresis with debounce, qualifier, scaled output)
 *
 * Hand-written software component (swc.yaml: implementation: c). Created once by tools/swc/swc_skeleton.py from
 * swc.yaml; from now on this file is yours, the tool never overwrites it. swc.yaml stays the description
 * the RTE is generated from: after changing runnables there,
 *     python tools/swc/swc_skeleton.py check <component folder>
 * lists runnable functions that are missing here or no longer described.
 * Rte_LevelMonSwc.h (generated by tools/rtegen) declares the runnables and the port accesses.
 *
 * RTE-20 example (test profile tools/rtegen/test/c_swc). Run10ms and Run100ms share the state below, so the ECU
 * description runs both in one task. */

#include "Rte_LevelMonSwc.h"
#include "Rte_Qlf.h"

#define LEVELMON_SAMPLES 4U           /* length of the moving average, = dim of the parameter Weights */
#define LEVELMON_GAIN_ONE 1000U       /* stored value of Gain 1.0 (lsb 0.001) */
#define LEVELMON_UINT16_MAX 0xFFFFU

static uint32 history_mV[LEVELMON_SAMPLES]; /* newest first */
static uint8 samples;                       /* valid entries of history_mV */
static uint8 debounce;                      /* cycles at or above OnLevel_mV while Above is off */
static boolean above;
static uint32 filtered_mV;
static uint16 crossings;                    /* rising edges of Above, saturating */

static uint32 weightedAverage(void)
{
    uint8 const* const weights = Rte_Prm_CalPrm_Weights();
    uint64 sum                 = 0U;
    uint32 weightSum           = 0U;
    uint32 result              = history_mV[0];
    uint8 i;
    for (i = 0U; i < LEVELMON_SAMPLES; ++i)
    {
        sum += (uint64)history_mV[i] * (uint64)weights[i];
        weightSum += (uint32)weights[i];
    }
    if (weightSum > 0U)
    {
        result = (uint32)(sum / (uint64)weightSum);
    }
    return result;
}

void LevelMonSwc_Init(void)
{
    uint8 i;
    for (i = 0U; i < LEVELMON_SAMPLES; ++i)
    {
        history_mV[i] = 0U;
    }
    samples     = 0U;
    debounce    = 0U;
    above       = FALSE;
    filtered_mV = 0U;
    crossings   = 0U;
}

/* Runnable Run10ms, every 10 ms: average, plausibility, hysteresis with debounce. */
void LevelMonSwc_Run10ms(void)
{
    uint32 level_mV = 0U;
    uint8 qlf       = QLF_DEBOUNCE;
    uint8 i;
    (void)Rte_Read_Level_mV_Level_mV(&level_mV);

    for (i = (uint8)(LEVELMON_SAMPLES - 1U); i > 0U; --i)
    {
        history_mV[i] = history_mV[i - 1U];
    }
    history_mV[0] = level_mV;
    if (samples < LEVELMON_SAMPLES)
    {
        ++samples;
    }
    filtered_mV = weightedAverage();

    if (samples < LEVELMON_SAMPLES)
    {
        /* the average is not filled yet: no statement about the level */
        above    = FALSE;
        debounce = 0U;
    }
    else if (filtered_mV > Rte_Prm_CalPrm_MaxLevel_mV())
    {
        qlf      = QLF_ERROR_RANGE;
        above    = FALSE;
        debounce = 0U;
    }
    else
    {
        qlf = QLF_OK;
        if (above == (boolean)FALSE)
        {
            if (filtered_mV >= Rte_Prm_CalPrm_OnLevel_mV())
            {
                ++debounce;
                if (debounce >= Rte_Prm_CalPrm_DebounceCycles())
                {
                    above    = TRUE;
                    debounce = 0U;
                    if (crossings < LEVELMON_UINT16_MAX)
                    {
                        ++crossings;
                    }
                }
            }
            else
            {
                debounce = 0U;
            }
        }
        else if (filtered_mV <= Rte_Prm_CalPrm_OffLevel_mV())
        {
            above = FALSE;
        }
        else
        {
            /* between the thresholds: Above keeps its state */
        }
    }

    (void)Rte_Write_Filtered_mV_Filtered_mV(filtered_mV);
    (void)Rte_Write_Above_Above(above);
    (void)Rte_Write_LevelQlf_LevelQlf(qlf);
}

/* Runnable Run100ms, every 100 ms: crossing count and the level times the fixed-point Gain, saturated. */
void LevelMonSwc_Run100ms(void)
{
    uint64 const scaled = ((uint64)filtered_mV * (uint64)Rte_Prm_CalPrm_Gain()) / (uint64)LEVELMON_GAIN_ONE;
    (void)Rte_Write_Crossings_Crossings(crossings);
    (void)Rte_Write_Scaled_Scaled((scaled > (uint64)LEVELMON_UINT16_MAX) ? (uint16)LEVELMON_UINT16_MAX
                                                                          : (uint16)scaled);
}
